import {orderedSources,orderedTests} from './ordered-sorting-content.mjs';
import {orderedView,validOrderedProgram,orderedBasketLabel,orderedOverlap,orderedPredicate,startOrdered,chooseOrderedCase,editOrdered,swapOrdered,selectOrderedParcel,predictOrdered,pageOrdered,restartOrdered,supportOrdered,learnOrdered,helpOrdered,contrastOrdered,compareOrdered,historyOrdered,stepOrdered} from './ordered-sorting-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const p=t=>`<p>${esc(t)}</p>`;
const testLabel=code=>orderedTests.find(t=>t.id===code)?.label||'Choose a test';
const basketLabel=(s,id)=>id?orderedBasketLabel(s,id):'choose a basket';
const testWords=r=>r?.test==='off'?'No second test':r?.test?`${r.not?'NOT ':''}${testLabel(r.test)}`:'choose a test';
function programText(s,program){return `If ${testWords(program.first)}, use ${basketLabel(s,program.first.basket)}.${program.second.test==='off'?' No second test.':` Otherwise, if ${testWords(program.second)}, use ${basketLabel(s,program.second.basket)}.`} Otherwise use ${basketLabel(s,program.otherwise)}.`;}
function cardArt(card,prefix='selected'){const large=card.size==='large',x=large?24:54,y=large?34:66,w=large?132:72,h=large?76:44,cx=90,cy=y+h/2,r=large?17:12,clip=`ordered-${prefix}-${card.id}`;const stamp=card.stamp==='circle'?`<circle cx="${cx}" cy="${cy}" r="${r}"/>`:card.stamp==='square'?`<rect x="${cx-r}" y="${cy-r}" width="${r*2}" height="${r*2}"/>`:`<path transform="translate(${cx} ${cy}) scale(${r/20})" d="M0-20 6-7 20-6 10 4 12 19 0 12-12 19-10 4-20-6-6-7Z"/>`;return `<svg class="ordered-art" viewBox="0 0 180 130" role="img" aria-label="${esc(card.title)}: ${card.size}; ${card.wrap} wrap; ${card.stamp} stamp" data-ordered-card data-size="${card.size}" data-wrap="${card.wrap}" data-stamp="${card.stamp}"><rect x="17" y="28" width="146" height="84" rx="8" fill="none" stroke="#a7baac" stroke-dasharray="4 4"/><defs><clipPath id="${clip}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6"/></clipPath></defs><rect data-ordered-size-box x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${card.wrap==='blue'?'#c8e1ed':'#f5df99'}" stroke="#244f45" stroke-width="3"/><g clip-path="url(#${clip})" ${card.wrap==='blue'?'stroke="#739eaf" stroke-width="4"':'fill="#ba903e"'}>${card.wrap==='blue'?[-30,0,30,60,90,120,150,180].map(n=>`<path d="M${n} 20l60 110"/>`).join(''):[35,60,85,110,135,160].map(n=>[45,68,91].map(m=>`<circle cx="${n}" cy="${m}" r="2.5"/>`).join('')).join('')}</g><circle cx="${cx}" cy="${cy}" r="${r+5}" fill="#fffdf6" stroke="#244f45" stroke-width="1.5"/><g fill="#397958" stroke="#183f39" stroke-width="1.5">${stamp}</g><text x="90" y="20" text-anchor="middle" font-size="14" fill="#203f46">${large?'Large':'Small'}</text></svg>`;}
function selectedCard(s,id,prefix){const card=s.parcels.find(x=>x.id===id);return card?`<figure class="ordered-selected">${cardArt(card,prefix)}<figcaption><strong>${esc(card.title)}</strong><br>${card.size} · ${card.wrap} wrap · ${card.stamp} stamp</figcaption></figure>`:'';}
const request=s=>`<aside class="ordered-request"><strong>Wren’s request</strong>${p(s.request)}</aside>`;
function selectField(s,w,row,field,label){const value=row==='otherwise'?w.program.otherwise:w.program[row][field],items=field==='test'?[{id:'',label:'Choose a test'},...(row==='second'?[{id:'off',label:'No second test'}]:[]),...orderedTests]:[{id:'',label:'Choose a basket'},...s.baskets],off=row==='second'&&w.program.second.test==='off'&&field==='basket';return `<label>${label}<select data-ordered-field="${row}-${field}"${off?' disabled':''}>${items.map(i=>`<option value="${esc(i.id)}"${(value??'')===i.id?' selected':''}>${esc(i.label)}</option>`).join('')}</select></label>`;}
function editor(w){const s=w.source;return `<section class="ordered-editor"><h3>Set the rules in order</h3>${['first','second'].map((row,i)=>`<fieldset class="ordered-rule-row"><legend>${i===0?'First rule':'Second rule, only if the first says No'}</legend>${selectField(s,w,row,'test','Test')}<label class="ordered-not"><input type="checkbox" data-ordered-not="${row}"${w.program[row].not?' checked':''}${row==='second'&&w.program.second.test==='off'?' disabled':''}>NOT: reverse this test’s answer</label>${selectField(s,w,row,'basket','Use this basket')}</fieldset>`).join('')}<fieldset class="ordered-rule-row"><legend>Otherwise</legend>${selectField(s,w,'otherwise','basket','If no active test matched')}</fieldset>${btn(`data-ordered-swap${!w.program.first.test||!w.program.second.test||w.program.second.test==='off'?' disabled':''}`,'Swap the two rules')}<p>Swapping moves each test, NOT choice and basket together.</p></section>`;}
function buildPage(w){const s=w.source;return `<h2 id="ordered-question" tabindex="-1">Which rule comes first?</h2>${request(s)}<div class="ordered-build"><section><label for="ordered-parcel">Choose a parcel<select id="ordered-parcel" data-ordered-parcel>${s.parcels.map(c=>`<option value="${esc(c.id)}"${w.selectedParcel===c.id?' selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${selectedCard(s,w.selectedParcel,'build')}${btn(`data-ordered-overlap${!w.program.first.test||!w.program.second.test||w.program.second.test==='off'?' disabled':''}`,'Find a parcel both tests catch')}<p>If two tests could catch the same parcel, the first match chooses its basket.</p></section>${editor(w)}</div><p id="ordered-rule" class="ordered-rule-sentence">${esc(programText(s,w.program))}</p>${btn('data-ordered-page="step"','Step one parcel',true)}${btn('data-ordered-page="compare"','Compare the supplied cards')}`;}
function stepText(step,s){if(step.kind==='test')return `${step.row==='first'?'First':'Second'} test: ${step.not?'NOT ':''}${testLabel(step.test)}? Recorded answer: ${step.yes?'Yes':'No'}. Observed ${step.feature}: ${step.observed}.`;return `${step.branch==='otherwise'?'Otherwise':step.branch==='first'?'First rule':'Second rule'} chooses ${basketLabel(s,step.basket)}. Exactly one basket is chosen. ${step.second==='not-tested'?'Second row: Not tested because the first rule matched.':step.second==='off'?'Second row: off, not tested.':'The second test was reached after the first said No.'}`;}
function baskets(s,actual=null,parcelId=null){const card=s.parcels.find(p=>p.id===parcelId);return `<div class="ordered-baskets" aria-label="Destination baskets">${s.baskets.map(b=>`<div class="ordered-basket${actual===b.id?' selected':''}" data-ordered-basket="${esc(b.id)}" data-selected="${actual===b.id}"><svg viewBox="0 0 90 65" aria-hidden="true">${actual===b.id&&card?`<g data-ordered-arrived-parcel data-stamp="${card.stamp}" data-wrap="${card.wrap}"><rect x="${card.size==='large'?29:35}" y="${card.size==='large'?3:10}" width="${card.size==='large'?32:20}" height="${card.size==='large'?31:24}" rx="3" fill="${card.wrap==='blue'?'#c8e1ed':'#f5df99'}" stroke="#244f45" stroke-width="2"/>${card.stamp==='circle'?'<circle cx="45" cy="17" r="4" fill="#397958"/>':card.stamp==='square'?'<rect x="41" y="13" width="8" height="8" fill="#397958"/>':'<path d="m45 10 2 4 5 1-4 3 1 5-4-2-4 2 1-5-4-3 5-1Z" fill="#397958"/>'}</g>`:''}<path d="M12 23H78L68 58H22Z" fill="${actual===b.id?'#d6b56d':'#e6dcc0'}" stroke="#365c4c" stroke-width="3"/><path d="M26 23C26 2 64 2 64 23M18 35H73M21 46H70M32 24V56M46 24V57M60 24V56" fill="none" stroke="#8a774e" stroke-width="2"/></svg><strong>${esc(b.label)}</strong>${actual===b.id?'<span>Parcel sent here</span>':''}</div>`).join('')}</div>`;}
const activeNot=program=>program.first.not||program.second.test!=='off'&&program.second.not;
const keyedReplies=(source,keys)=>`<aside class="ordered-keyed-replies">${keys.map(key=>`<p data-ordered-reply="${key}">${esc(source.text[key])}</p>`).join('')}</aside>`;
function resultReplies(run){const keys=[],choice=run.steps.find(x=>x.kind==='choose'),card=run.source.parcels.find(x=>x.id===run.parcelId);if(choice?.second==='not-tested')keys.push('firstMatch');if(run.program.second.test!=='off'&&orderedPredicate(run.program.first.test,run.program.first.not,card)&&orderedPredicate(run.program.second.test,run.program.second.not,card))keys.push('overlap');if(activeNot(run.program))keys.push('notReply');return keyedReplies(run.source,keys);}
function comparisonReplies(comparison){const keys=[];if(comparison.matchCount===comparison.rows.length)keys.push('finite');keys.push('equivalent');if(activeNot(comparison.program)||activeNot(comparison.source.requestProgram))keys.push('notReply');return keyedReplies(comparison.source,keys);}
function runRecord(run,prefix='kept'){return `<article class="ordered-record" data-ordered-record><h3>Recorded run ${run.id}</h3>${request(run.source)}<p>${esc(programText(run.source,run.program))}</p>${selectedCard(run.source,run.parcelId,prefix)}<ol>${run.steps.map(x=>`<li>${esc(stepText(x,run.source))}</li>`).join('')}</ol><p>Recorded destination: <strong>${esc(basketLabel(run.source,run.actualBasket))}</strong>. Requested destination: <strong>${esc(basketLabel(run.source,run.requestedBasket))}</strong>.</p><p>Recorded request match: ${run.matches?'yes':'no'}. Prediction before stepping: ${esc(run.prediction==='unsure'?'not sure':run.prediction?basketLabel(run.source,run.prediction):'none')}.</p>${resultReplies(run)}</article>`;}
function nextAction(w){const t=w.trace;if(!t)return 'Read the first test';if(t.phase==='first')return t.steps[0].yes?'Use the first matching rule':t.program.second.test==='off'?'Use Otherwise':'Read the second test';if(t.phase==='second')return 'Choose the matching basket';if(t.phase==='chosen')return 'Send this parcel';return null;}
function evictionDialog(c){return c.needsEviction?`<dialog id="ordered-eviction"><div class="dialog-content"><h2>Keep this new run?</h2><p>Sending replaces the oldest readable recent run, number ${c.oldest.run.id}. Your first kept run and unreadable records stay.</p><p>You can download notes first. Nothing changes until you confirm.</p>${btn('data-ordered-download','Download notes first')}${btn('data-ordered-evict-cancel','Keep earlier work')}${btn(`data-ordered-evict-confirm="${c.oldest.run.id}"`,'Replace this one and send',true)}</div></dialog>`:'';}
function stepPage(c){const w=c.work,t=w.trace,s=t?.source||w.source,program=t?.program||w.program,parcelId=t?.parcelId||w.selectedParcel,action=nextAction(w);return `<h2 id="ordered-question" tabindex="-1">${!t?'What will your rule do?':t.phase==='sent'?'One parcel, one basket':action}</h2>${request(s)}<div class="ordered-step-board">${selectedCard(s,parcelId,'step')}<section><p id="ordered-rule" class="ordered-rule-sentence">${esc(programText(s,program))}</p>${t?'<p>This trace keeps the parcel and rule you started with. Edit the rule or restart to begin a new trace.</p>':''}${!t?`<fieldset class="ordered-prediction"><legend>Before stepping, which basket do you predict?</legend><div class="ordered-actions">${s.baskets.map(b=>btn(`data-ordered-predict="${esc(b.id)}" aria-pressed="${w.prediction===b.id}"`,b.label)).join('')}${btn(`data-ordered-predict="unsure" aria-pressed="${w.prediction==='unsure'}"`,'Not sure yet')}${btn(`data-ordered-predict="none" aria-pressed="${w.prediction===null}"`,'No prediction')}</div><p>Optional and unscored. Your prediction stays fixed after the first test.</p></fieldset>`:''}${t?`<ol class="ordered-trace" data-ordered-trace>${t.steps.map(step=>`<li>${esc(stepText(step,s))}</li>`).join('')}</ol>`:'<p>Start at the first row. A Yes stops the rule search; a No lets the next active test run.</p>'}${action?btn(`data-ordered-step${!t&&!validOrderedProgram(w.source,w.program)?' disabled':''}`,action,true):''}${!t&&!validOrderedProgram(w.source,w.program)?'<p>Choose both required tests and their baskets on Build rule, or explicitly choose No second test.</p>':''}${t?btn('data-ordered-restart','Start this trace again'):''}</section></div>${t?.phase==='sent'?c.resultAvailable?`<section class="ordered-result" data-ordered-result tabindex="-1"><h3>Recorded result</h3><p>Your rule sent this parcel to <strong>${esc(basketLabel(c.result.source,c.result.actualBasket))}</strong>. Wren requested <strong>${esc(basketLabel(c.result.source,c.result.requestedBasket))}</strong>.</p>${p(c.result.matches?c.result.source.text.match:c.result.source.text.mismatch)}${resultReplies(c.result)}${baskets(c.result.source,c.result.actualBasket,c.result.parcelId)}</section>`:'<section class="ordered-result"><h3>This earlier result cannot be read here</h3><p>Its original record stays in notes. No older result was used instead. Restart the trace or inspect another record.</p><a href="#notes">Open notes</a></section>':baskets(s)}${c.needsEviction?`<p class="ordered-retention">The next sent run replaces recent run ${c.oldest.run.id}, only after confirmation. Your first kept run stays separately.</p>`:'<p class="ordered-retention">The first sent run and latest eight readable runs stay kept. Sending a new run never removes an unreadable record.</p>'}<div class="ordered-actions">${btn('data-ordered-page="build"','Revise the rule')}${btn('data-ordered-page="compare"','Compare the supplied cards')}</div>${evictionDialog(c)}`;}
function comparisonCurrent(w,c){return JSON.stringify(w.source)===JSON.stringify(c.source)&&JSON.stringify(w.program)===JSON.stringify(c.program);}
function comparisonTable(c){return `<section data-ordered-comparison tabindex="-1"><p>Recorded matches: <strong>${c.matchCount} of ${c.rows.length} supplied cards</strong>. This comparison applies to the cards shown, not arbitrary parcels.</p><p>${esc(programText(c.source,c.program))}</p><div class="ordered-table-wrap"><table><caption>Recorded routes for the supplied parcel cards</caption><thead><tr><th scope="col">Parcel</th><th scope="col">Your rule</th><th scope="col">Requested</th><th scope="col">Match?</th></tr></thead><tbody>${c.rows.map(row=>{const card=c.source.parcels.find(x=>x.id===row.parcelId);return `<tr data-ordered-compare-row="${esc(row.parcelId)}" data-match="${row.matches}"><th scope="row">${cardArt(card,'comparison')}<span>${esc(card.title)}</span></th><td>${esc(basketLabel(c.source,row.actualBasket))}</td><td>${esc(basketLabel(c.source,row.requestedBasket))}</td><td>${row.matches?'Yes':'Different'}</td></tr>`;}).join('')}</tbody></table></div>${comparisonReplies(c)}</section>`;}
function historyChooser(c){const w=c.work,entries=new Map();if(c.firstKept)entries.set(c.firstKept.id,`First kept run ${c.firstKept.id}`);for(const {run} of c.readable)if(!entries.has(run.id))entries.set(run.id,`Run ${run.id}`);return entries.size?`<label for="ordered-history">Look at one earlier run<select id="ordered-history" data-ordered-history><option value="">Choose a recorded run</option>${[...entries].map(([id,label])=>`<option value="${id}"${w.historyId===id&&w.page==='history'?' selected':''}>${esc(label)}</option>`).join('')}</select></label>`:'<p>No sent run is kept yet.</p>';}
function comparePage(c){const w=c.work,s=w.source;return `<h2 id="ordered-question" tabindex="-1">Does the rule fit every supplied card?</h2>${request(s)}<p id="ordered-rule">${esc(programText(s,w.program))}</p><p>One matching parcel may miss a difference. Compare the actual route with the request for each supplied card.</p><p>A new comparison replaces only the latest comparison shown here. Earlier sent runs stay kept.</p>${btn(`data-ordered-compare${!validOrderedProgram(s,w.program)?' disabled':''}`,`Check all ${s.parcels.length} supplied cards`,true)}${c.comparisonStatus==='ready'?`<h3>${comparisonCurrent(w,w.comparison)?'Comparison of the current rule':'Earlier recorded comparison'}</h3>${comparisonTable(w.comparison)}`:c.comparisonStatus==='recovery'?'<p>An earlier comparison cannot be read here. It remains in notes. Other records and the rule editor are available.</p>':''}${historyChooser(c)}${c.unreadable.length?`<p>${c.unreadable.length} unreadable recent record(s) stay in <a href="#notes">your notes</a>.</p>`:''}${btn('data-ordered-page="build"','Back to the rule')}`;}
function historyPage(c){return `<h2 id="ordered-question" tabindex="-1">One earlier run</h2>${historyChooser(c)}${c.history?runRecord(c.history,'history'):'<p>This selected record is unavailable here. It stays in your notes; choose another readable run.</p>'}<div class="ordered-actions">${btn('data-ordered-page="step"','Back to the waiting trace')}${btn('data-ordered-page="compare"','Back to comparisons')}</div>`;}
function supportPanel(w){return `<section class="ordered-learning"><h3>One idea at a time</h3>${w.folded?btn('data-ordered-fold="false"','Show me how'):`${w.source.learn.slice(0,w.learnSeen).map(p).join('')}${w.learnSeen<w.source.learn.length?btn('data-ordered-learn','Next teaching line'):''}<aside class="ordered-guided">${w.source.guided.map(p).join('')}</aside>${btn('data-ordered-fold="true"','I know this, show me the rule')}`}<div class="ordered-help">${w.helpStage===1?`<h4>A hint</h4>${p(w.source.hint)}`:w.helpStage===2?`<h4>A different pictured example</h4><section data-ordered-example><p>${esc(programText(w.source,w.source.example.program))}</p><div class="ordered-example-cards">${w.source.example.parcels.map(card=>`<figure>${cardArt(card,'example')}<figcaption>${esc(card.title)}</figcaption></figure>`).join('')}</div><ol>${w.source.example.steps.map(step=>`<li>${esc(step.text)}</li>`).join('')}</ol></section>${p(w.source.start)}`:w.helpStage===3?p(w.source.skip):''}${btn('data-ordered-help',w.helpStage===0?'I’m stuck':w.helpStage===1?'Show a different example':w.helpStage===2?'Skip for now':'Read the hint again')}</div><div class="ordered-actions">${btn(`data-ordered-together${w.support.together?' disabled':''}`,w.support.together?'Working together recorded':'We’re working together')}<span data-ordered-audio>${hearButton(w.source.request,'Hear this request','en')}</span></div></section>`;}
export const orderedEntry=()=>'<aside class="ordered-entry"><a class="secondary" href="#post/sorting/order">Which test first?</a><p>Try three baskets, ordered rules, and turning one test around with NOT.</p></aside>';
export function orderedPage(state){const v=orderedView(state),c=v.case,w=c?.work,options=new Map(orderedSources.map(s=>[s.id,{id:s.id,title:s.title}]));for(const [id,cv] of Object.entries(v.cases||{}))options.set(id,{id,title:cv.status==='ready'?cv.work.source.title:`Earlier case: ${id}`});return `<section class="ordered-sheet" data-ordered-root lang="en"><header><a class="back" href="#post/sorting">Back to Sorting Desk</a><h1>Which test first?</h1><p>Wren needs recovery parcels routed to three baskets. Build a rule, watch its first match, and find a difference.</p></header>${v.status==='recovery'?'<h2 id="ordered-question" tabindex="-1">Your earlier desk stays safe</h2><p>This format cannot be edited here. Its original data stays in notes; other sorting games remain open.</p><a href="#notes">Open notes</a>':`<div class="ordered-cases" role="group" aria-label="Choose a request">${[...options].map(([id,item])=>btn(`data-ordered-case="${esc(id)}" aria-pressed="${v.currentCaseId===id}"`,item.title,v.currentCaseId===id)).join('')}</div>${v.status==='missing'?'<h2 id="ordered-question" tabindex="-1">Choose a request above to begin</h2><p>Each request keeps its own rule and parcel. All three are open.</p>':!c||c.status!=='ready'||c.traceStatus!=='ready'?'<h2 id="ordered-question" tabindex="-1">This earlier case is kept in notes</h2><p>Its current rule or trace cannot be edited safely here. Choose another request; the earlier raw work stays unchanged.</p><a href="#notes">Open notes</a>':`<nav class="ordered-pages" aria-label="Sorting pages">${['build','step','compare'].map(page=>btn(`data-ordered-page="${page}" aria-current="${w.page===page?'page':'false'}"`,page==='build'?'Build rule':page==='step'?'Step one parcel':'Compare routes',w.page===page)).join('')}</nav>${w.page==='build'?buildPage(w):w.page==='step'?stepPage(c):w.page==='compare'?comparePage(c):historyPage(c)}${w.page!=='history'?supportPanel(w):''}`}`}<p id="ordered-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a href="#notes">Grown-up notes</a><a href="#post/sorting">Original Sorting Desk</a><a href="#post/double-check">Double Check</a></footer></section>`;}
export const orderedRefusal=()=>'<section class="ordered-sheet" data-ordered-root><h1 id="ordered-question" tabindex="-1">Which test first?</h1><p>This explanation could not be opened while keeping earlier work exportable. Your earlier rule and records stay unchanged.</p><a href="#notes">Download notes</a><a href="#post/sorting">Original Sorting Desk</a><p id="ordered-status" role="status" tabindex="-1"></p></section>';
export function orderedNotes(state){return Object.hasOwn(state,'orderedSorting')?`<details class="panel"><summary>Which test first? · ordered rule investigations</summary><p>Supplied-rule traces, optional predictions, comparison results and shown/requested support stay separate. First-match practice on supplied parcel cards does not establish independent coding, mastery or a trained classifier. Frozen sources and recorded outcomes stay as kept; unreadable siblings remain below.</p><pre>${esc(JSON.stringify(state.orderedSorting,null,2))}</pre></details>`:'';}
export function bindOrdered(state,{save,render,focus,canExport,downloadNotes,explorerId,isActive}){const root=document.querySelector('[data-ordered-root]');if(!root)return;const hash=location.hash,owner=explorerId?.();let boundRoot=state.orderedSorting;const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===hash&&state.orderedSorting===boundRoot&&explorerId?.()===owner&&(!isActive||isActive());
 const say=(message,takeFocus=true)=>{const el=document.querySelector('#ordered-status');if(el){el.textContent=message;if(takeFocus)el.focus();}};
 const fail=()=>say('This change could not be kept safely. Your earlier rule and records stay here. Download notes or choose another place.');
 const redraw=(message='',target='#ordered-question')=>{stopSpeech();save();render();if(message)say(message,false);focus?.(document.querySelector(target)?target:'#ordered-question');};
 const click=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',e=>{if(!live(el)){e.preventDefault();e.stopImmediatePropagation();return;}fn(el);}));
 click('[data-ordered-case]',el=>(orderedView(state).status==='missing'?startOrdered:chooseOrderedCase)(state,el.dataset.orderedCase,canExport)?redraw():fail());
 click('[data-ordered-page]',el=>pageOrdered(state,el.dataset.orderedPage,canExport)?redraw():fail());
 root.querySelectorAll('[data-ordered-field]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const [row,field]=el.dataset.orderedField.split('-'),value=el.value||null;if(!editOrdered(state,row,field,value,canExport)){const w=orderedView(state).case.work;el.value=(row==='otherwise'?w.program.otherwise:w.program[row][field])??'';return fail();}redraw('Rule updated. Earlier sent runs stay kept.',`[data-ordered-field="${el.dataset.orderedField}"]`);}));
 root.querySelectorAll('[data-ordered-not]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;if(!editOrdered(state,el.dataset.orderedNot,'not',el.checked,canExport)){el.checked=orderedView(state).case.work.program[el.dataset.orderedNot].not;return fail();}redraw('This test’s NOT setting changed.',`[data-ordered-not="${el.dataset.orderedNot}"]`);}));
 root.querySelector('[data-ordered-parcel]')?.addEventListener('change',e=>{if(!live(e.target))return;if(!selectOrderedParcel(state,e.target.value,canExport)){e.target.value=orderedView(state).case.work.selectedParcel;return fail();}redraw('Parcel selected. Your rule stays in place.','[data-ordered-parcel]');});
 click('[data-ordered-swap]',()=>swapOrdered(state,canExport)?redraw('The two complete rules swapped. Earlier records stay kept.','[data-ordered-swap]'):fail());
 click('[data-ordered-overlap]',()=>{const w=orderedView(state).case.work,witness=orderedOverlap(w.source,w.program);if(!contrastOrdered(state,canExport))return fail();redraw(witness?'This supplied parcel passes both tests. Step your rule to see which one wins.':'No supplied parcel passes both of these chosen tests. The parcel and rule stay here.','[data-ordered-overlap]');});
 click('[data-ordered-predict]',el=>predictOrdered(state,el.dataset.orderedPredict==='none'?null:el.dataset.orderedPredict,canExport)?redraw('',`[data-ordered-predict="${el.dataset.orderedPredict}"]`):fail());
 const send=confirmed=>{if(!stepOrdered(state,canExport,confirmed))return fail();const sent=orderedView(state).case.work.trace?.phase==='sent';redraw('The machine advanced one step.',sent?'[data-ordered-result]':'[data-ordered-step]');};
 click('[data-ordered-step]',()=>{const c=orderedView(state).case;if(c.work.trace?.phase==='chosen'&&c.needsEviction){root.querySelector('#ordered-eviction')?.showModal();return;}send(null);});
 click('[data-ordered-evict-confirm]',el=>{root.querySelector('#ordered-eviction')?.close();send(Number(el.dataset.orderedEvictConfirm));});
 click('[data-ordered-evict-cancel]',()=>root.querySelector('#ordered-eviction')?.close());
 click('[data-ordered-download]',()=>downloadNotes?.());
 click('[data-ordered-restart]',()=>restartOrdered(state,canExport)?redraw('This trace restarted; earlier sent runs remain.','[data-ordered-step]'):fail());
 click('[data-ordered-compare]',()=>compareOrdered(state,canExport)?redraw('The current rule was compared with every supplied card.','[data-ordered-comparison]'):fail());
 root.querySelector('[data-ordered-history]')?.addEventListener('change',e=>{if(!live(e.target))return;const id=e.target.value===''?null:Number(e.target.value);if(!historyOrdered(state,id,canExport)){e.target.value=String(orderedView(state).case.work.historyId??'');return fail();}redraw('One recorded run is open.','[data-ordered-history]');});
 click('[data-ordered-help]',()=>helpOrdered(state,canExport)?redraw('Help changed. The rule and parcel stay waiting.','[data-ordered-help]'):fail());
 click('[data-ordered-learn]',()=>learnOrdered(state,'next',canExport)?redraw('Next teaching line.','[data-ordered-learn], [data-ordered-fold]'):fail());
 click('[data-ordered-fold]',el=>learnOrdered(state,el.dataset.orderedFold==='true'?'fold':'unfold',canExport)?redraw('Teaching preference kept.','[data-ordered-fold]'):fail());
 click('[data-ordered-together]',()=>supportOrdered(state,'together',canExport)?redraw('Working together kept with this case.'):fail());
 root.querySelectorAll('[data-ordered-audio] [data-speak]').forEach(el=>el.addEventListener('click',e=>{if(!live(el)){e.stopImmediatePropagation();return;}if(!supportOrdered(state,'audio',canExport)){e.stopImmediatePropagation();fail();return;}boundRoot=state.orderedSorting;save();},true));
}
